// ComponentServiceServer is the server API for ComponentService service.
// All implementations must embed UnimplementedComponentServiceServer
// for forward compatibility.
//
// ComponentService is the central gRPC service that all Gibson components
// (agents, tools, and plugins) connect to. Components register themselves,
// receive work via long-polling, submit results, and access harness operations
// (LLM completion, tool calls, plugin queries, findings, memory) through
// the proxy RPCs defined here.
type ComponentServiceServer interface {
	// RegisterComponent announces a component to Gibson and receives connection
	// configuration including heartbeat and poll intervals.
	RegisterComponent(context.Context, *RegisterComponentRequest) (*RegisterComponentResponse, error)
	// Heartbeat sends a periodic health pulse. The response indicates whether
	// the component is still considered registered and may carry config updates.
	Heartbeat(context.Context, *HeartbeatRequest) (*HeartbeatResponse, error)
	// PollWork long-polls for work items assigned to this component instance.
	// Returns when a work item is available or the server-side timeout expires.
	//
	// Authorized by can_poll_work, not can_execute: PollWork/SubmitResult are
	// the receive-side of dispatch (how a component gets its work), distinct
	// from CallTool/RunMission's drive-side (how a component directs the
	// platform). Sharing can_execute would let a poll-only grant also drive
	// missions. can_poll_work is modeled as `can_execute or can_receive_work`,
	// so existing can_execute holders keep polling unchanged.
	PollWork(context.Context, *PollWorkRequest) (*PollWorkResponse, error)
	// SubmitResult returns the execution result for a previously polled work item.
	//
	// Authorized by can_poll_work — see PollWork's comment for why this
	// receive-side RPC does not share can_execute with the drive-side RPCs.
	SubmitResult(context.Context, *SubmitResultRequest) (*SubmitResultResponse, error)
	// Complete proxies an LLM completion request through the agent harness.
	Complete(context.Context, *CompleteRequest) (*CompleteResponse, error)
	// CompleteStream proxies a streaming LLM completion request through the agent harness.
	CompleteStream(*CompleteStreamRequest, grpc.ServerStreamingServer[CompleteStreamResponse]) error
	// CallTool proxies a tool execution request through the agent harness.
	CallTool(context.Context, *CallToolRequest) (*CallToolResponse, error)
	// QueryPlugin proxies a plugin query request through the agent harness.
	QueryPlugin(context.Context, *QueryPluginRequest) (*QueryPluginResponse, error)
	// SubmitFinding submits a security finding through the agent harness.
	SubmitFinding(context.Context, *SubmitFindingRequest) (*SubmitFindingResponse, error)
	// ListAvailablePlugins returns all plugins registered in the system along
	// with their catalog metadata, health status, and configuration schema.
	ListAvailablePlugins(context.Context, *ListAvailablePluginsRequest) (*ListAvailablePluginsResponse, error)
	// EnablePlugin activates a plugin for the calling tenant, optionally
	// supplying an initial configuration JSON blob.
	EnablePlugin(context.Context, *EnablePluginRequest) (*EnablePluginResponse, error)
	// DisablePlugin deactivates a plugin for the calling tenant.
	DisablePlugin(context.Context, *DisablePluginRequest) (*DisablePluginResponse, error)
	// UpdatePluginConfig replaces the configuration for an already-enabled plugin.
	UpdatePluginConfig(context.Context, *UpdatePluginConfigRequest) (*UpdatePluginConfigResponse, error)
	// GetPluginConfig retrieves the current configuration and schema for a plugin.
	GetPluginConfig(context.Context, *GetPluginConfigRequest) (*GetPluginConfigResponse, error)
	// TestPluginConnection validates connectivity and credentials for a plugin
	// without persisting any state changes.
	TestPluginConnection(context.Context, *TestPluginConnectionRequest) (*TestPluginConnectionResponse, error)
	// ListTenantPlugins returns the plugin access records for the calling tenant.
	ListTenantPlugins(context.Context, *ListTenantPluginsRequest) (*ListTenantPluginsResponse, error)
	// CompleteWithTools proxies an LLM completion with tool definitions for
	// function-calling support. Returns the response including any tool calls.
	CompleteWithTools(context.Context, *CompleteWithToolsRequest) (*CompleteWithToolsResponse, error)
	// CompleteStructured proxies an LLM completion requesting JSON output
	// conforming to the supplied schema.
	CompleteStructured(context.Context, *CompleteStructuredRequest) (*CompleteStructuredResponse, error)
	// CallToolStream proxies a tool execution with server-side streaming of
	// progress, partial results, warnings, and the final output.
	CallToolStream(*CallToolStreamRequest, grpc.ServerStreamingServer[CallToolStreamResponse]) error
	// QueueToolWork submits a batch of tool invocations for parallel execution
	// and returns a job ID for tracking.
	QueueToolWork(context.Context, *QueueToolWorkRequest) (*QueueToolWorkResponse, error)
	// ToolResults streams results for a previously queued tool batch as each
	// invocation completes.
	ToolResults(*ToolResultsRequest, grpc.ServerStreamingServer[ToolResultsResponse]) error
	// ListTools returns descriptors for all tools visible to the caller's tenant.
	ListTools(context.Context, *ListToolsRequest) (*ListToolsResponse, error)
	// DelegateToAgent dispatches a sub-task to another agent and returns its result.
	DelegateToAgent(context.Context, *DelegateToAgentRequest) (*DelegateToAgentResponse, error)
	// ListAgents returns descriptors for all agents visible to the caller's tenant.
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// QueryNodes searches the knowledge graph using hybrid vector + graph scoring.
	QueryNodes(context.Context, *QueryNodesRequest) (*QueryNodesResponse, error)
	// FindSimilarAttacks returns attack patterns semantically similar to the given content.
	FindSimilarAttacks(context.Context, *FindSimilarAttacksRequest) (*FindSimilarAttacksResponse, error)
	// GetAttackChains returns multi-hop attack paths from a starting technique.
	GetAttackChains(context.Context, *GetAttackChainsRequest) (*GetAttackChainsResponse, error)
	// FindSimilarFindings returns findings semantically similar to the given finding.
	FindSimilarFindings(context.Context, *FindSimilarFindingsRequest) (*FindSimilarFindingsResponse, error)
	// GetRelatedFindings returns findings related to the given finding via graph edges.
	GetRelatedFindings(context.Context, *GetRelatedFindingsRequest) (*GetRelatedFindingsResponse, error)
	// GetFindings queries previously submitted findings with optional filters.
	GetFindings(context.Context, *GetFindingsRequest) (*GetFindingsResponse, error)
	// GetRunFindings queries findings scoped to a specific mission run or across all runs.
	GetRunFindings(context.Context, *GetRunFindingsRequest) (*GetRunFindingsResponse, error)
	// CreateMission creates a new sub-mission.
	CreateMission(context.Context, *CreateMissionRequest) (*CreateMissionResponse, error)
	// RunMission queues a mission for execution.
	RunMission(context.Context, *RunMissionRequest) (*RunMissionResponse, error)
	// GetMissionStatus returns the current status of a mission.
	GetMissionStatus(context.Context, *GetMissionStatusRequest) (*GetMissionStatusResponse, error)
	// WaitMission blocks until a mission completes or the timeout expires.
	WaitMission(context.Context, *WaitMissionRequest) (*WaitMissionResponse, error)
	// ListMissions returns missions matching the given filter.
	ListMissions(context.Context, *ListMissionsRequest) (*ListMissionsResponse, error)
	// CancelMission requests cancellation of a running mission.
	CancelMission(context.Context, *CancelMissionRequest) (*CancelMissionResponse, error)
	// GetMissionResults returns the final results of a completed mission.
	GetMissionResults(context.Context, *GetMissionResultsRequest) (*GetMissionResultsResponse, error)
	// GetCredential retrieves a tenant-scoped credential by name.
	GetCredential(context.Context, *GetCredentialRequest) (*GetCredentialResponse, error)
	// GetTaxonomySchema returns the current taxonomy definition.
	GetTaxonomySchema(context.Context, *GetTaxonomySchemaRequest) (*GetTaxonomySchemaResponse, error)
	// GetMissionRunHistory returns summaries of previous mission runs.
	GetMissionRunHistory(context.Context, *GetMissionRunHistoryRequest) (*GetMissionRunHistoryResponse, error)
	// ReportStepHints reports planning step hints from an agent back to the orchestrator.
	ReportStepHints(context.Context, *ReportStepHintsRequest) (*ReportStepHintsResponse, error)
	mustEmbedUnimplementedComponentServiceServer()
}

